/**
 * LOCATORS: App.js has no testID / accessibilityLabel, so everything is text based.
 * If you add testID props in the app, swap these for `$('id=<package>:id/<testID>')`
 * (React Native maps testID -> Android resource-id).
 */

export type NavLabel = 'Dashboard' | 'Services' | 'Transact' | 'History' | 'Account';
export type FilterLabel = 'All' | 'Pending' | 'Completed';

const esc = (v: string) => v.replace(/"/g, '\\"');
const byText = (v: string) => `android=new UiSelector().text("${esc(v)}")`;
const lower = (attr: string) => `translate(${attr},'ABCDEFGHIJKLMNOPQRSTUVWXYZ','abcdefghijklmnopqrstuvwxyz')`;

class PrimeFinPage {
  // ---------- login ----------
  get signInButton() { return $(byText('Sign In')); }
  get welcomeAlertTitle() { return $(byText('Welcome back')); }
  get alertOkButton() { return $('id=android:id/button1'); }

  // ---------- bottom navigation (label also appears as a screen title, so take the last match) ----------
  navItem(label: NavLabel) { return $(`(//android.widget.TextView[@text="${label}"])[last()]`); }

  // ---------- dashboard ----------
  // heroTitle uses textTransform: 'uppercase', so match case-insensitively.
  // The value is the TextView right after the title inside the same card.
  heroCardValue(title: string) {
    return $(
      `//android.widget.TextView[${lower('@text')}="${title.toLowerCase()}"]/following-sibling::android.widget.TextView[1]`,
    );
  }

  // ---------- transact ----------
  // "Available" sits directly under the balance inside "From Account".
  get availableBalanceValue() {
    return $('//android.widget.TextView[@text="Available"]/preceding-sibling::android.widget.TextView[1]');
  }

  // ---------- history ----------
  get historySummaryLabel() { return $(byText('Total Spending (May)')); }
  filterChip(label: FilterLabel) { return $(byText(label)); }
  get emptyHistoryCard() { return $(byText('No transactions yet')); }
  rowTitle(title: string) { return $(byText(title)); }

  /**
   * statusPillText uses textTransform: 'uppercase', the filter chips do not: "PENDING" vs "Pending".
   * If Appium Inspector shows the pill in mixed case on your device, change .toUpperCase() here only.
   */
  statusPillSelector(status?: string) {
    return byText((normaliseStatus(status) || 'unknown').toUpperCase());
  }

  // ---------- actions ----------
  async login() {
    await this.signInButton.waitForDisplayed({ timeout: 30000 });
    await this.signInButton.click();
    await this.welcomeAlertTitle.waitForDisplayed({ timeout: 20000 });
    await this.alertOkButton.click();
  };
  
async openTab(label: NavLabel) {

    const tab = await $(
        `android=new UiSelector().description("Γå║, ${label}")`
    );

    await tab.waitForDisplayed({ timeout: 10000 });
    await tab.waitForEnabled({ timeout: 10000 });

    console.log('NAVIGATION ELEMENT:', await tab.getAttribute('content-desc'));

    // Tap the clickable navigation parent
    await tab.click();

    await browser.pause(2000);

    // Check whether the screen changed
    const source = await browser.getPageSource();

    console.log('HISTORY SCREEN:', source.includes('Total Spending (May)'));
    console.log('DASHBOARD SCREEN:', source.includes('Quick Actions'));

    const marker: Record<NavLabel, string> = {
        Dashboard: 'Quick Actions',
        Services: 'Select Network',
        Transact: 'From Account',
        History: 'Total Spending (May)',
        Account: 'Security',
    };

    const screenMarker = await $(
        `android=new UiSelector().text("${marker[label]}")`
    );

    await screenMarker.waitForDisplayed({
        timeout: 15000,
        timeoutMsg: `Tapped "${label}" but its screen never appeared`
    });

    console.log(`Successfully navigated to ${label}`);
}


  /** formatCurrency(null) renders "R 0.00" until loadSessionData() finishes, so wait for a non-zero value. */
  async waitForBalanceLoaded() {
    await browser.waitUntil(
      async () => parseZar(await this.heroCardValue('Total Net Worth').getText()) > 0,
      { timeout: 20000, timeoutMsg: 'Dashboard balance never loaded (still R 0.00)' },
    );
  }

  async dashboardBalance(): Promise<number> {
    return parseZar(await this.heroCardValue('Total Net Worth').getText());
  }

  async transferScreenBalance(): Promise<number> {
  await $(byText('From Account')).waitForDisplayed({ timeout: 10000 });
  const amount = $('android=new UiSelector().textMatches("^-?R.{0,2}[0-9].*").instance(0)');
  await amount.waitForDisplayed({ timeout: 10000 });
  return parseZar(await amount.getText());
}

  /** Scrolls the History ScrollView until a row with this title is on screen. */
  async scrollToRow(title: string) {
    const el = await $(
      `android=new UiScrollable(new UiSelector().scrollable(true)).setMaxSearchSwipes(20).scrollIntoView(new UiSelector().text("${esc(title)}"))`,
    );
    await el.waitForDisplayed({ timeout: 10000 });
    return el;
  }

  async countStatusPills(status?: string): Promise<number> {
    return (await $$(this.statusPillSelector(status))).length;
  }

  /** Every ZAR amount currently visible, parsed to numbers (rows, summary card...). */
  async visibleAmounts(): Promise<number[]> {
    const els = await $$('android=new UiSelector().textMatches("^-?R.{0,2}[0-9].*")');
    const texts = await els.map((e) => e.getText());
    return texts.map(parseZar);
  }
}

export default new PrimeFinPage();

// Android transfer scenarios use the mobile UI and a separate API session for verification.
import { Before, Given, When, Then } from '@wdio/cucumber-framework';
import { expect } from '@wdio/globals';
import page from './primefin.page';
import transferPage, { MobileTransferResult } from './transfer.page';
import { normaliseStatus, round2 } from '../support/helpers';
import {
  authorize, getAccounts, getBalance, getHistory, getTransaction, loginAs, transfer,
  HistoryTx, Session, TransferResult,
} from '../support/transferApi';

interface ConcurrencyState {
  web: Session;
  senderName?: string;
  recipientId?: number;
  recipientName?: string;
  recipientBalance?: number;
  originalBalance?: number;
  originalIds?: Set<number>;
  mobileAmount?: number;
  webAmount?: number;
  webResult?: TransferResult;
  mobileResult?: MobileTransferResult;
  newTxs?: HistoryTx[];
}

let state: ConcurrencyState | undefined;
const st = (): ConcurrencyState => {
  if (!state) throw new Error('State missing: an account setup step must run first');
  return state;
};
const sleep = (ms: number) => new Promise((r) => setTimeout(r, ms));

Before({ tags: '@concurrency' }, async () => {
  state = undefined;
});

Before({ tags: '@mobile-transfer' }, async () => {
  state = undefined;
});

/** Polls the history until at least `atLeast` transactions that did not exist before the test are visible. */
async function waitForNewTransactions(s: ConcurrencyState, atLeast: number): Promise<HistoryTx[]> {
  const deadline = Date.now() + 10000;
  let fresh: HistoryTx[] = [];
  do {
    const history = await getHistory(s.web);
    fresh = history.filter((t) => !(s.originalIds as Set<number>).has(t.id));
    if (fresh.length >= atLeast) break;
    await sleep(500);
  } while (Date.now() < deadline);
  return fresh;
}

async function initializeState(): Promise<ConcurrencyState> {
  await page.login();
  await page.waitForBalanceLoaded();

  const s: ConcurrencyState = { web: await loginAs('web') };
  const accounts = await getAccounts(s.web);
  const sender = accounts.find((a) => a.id === s.web.userId);
  const recipient = accounts.find((a) => a.id !== s.web.userId);
  if (!sender) throw new Error(`Could not find the signed-in account with ID ${s.web.userId}`);
  if (!recipient) throw new Error('The database needs a second account to act as the transfer recipient');
  s.senderName = sender.full_name;
  s.recipientId = recipient.id;
  s.originalBalance = round2(await getBalance(s.web));
  s.originalIds = new Set((await getHistory(s.web)).map((t) => t.id));
  state = s;
  return s;
}

// ---------- setup ----------
Given('the account balance is R{float}', async (expectedBalance: number) => {
  const s = await initializeState();
  if (s.originalBalance !== round2(expectedBalance)) {
    throw new Error(
      `Precondition failed: expected the account balance to be R${expectedBalance}, but the database has R${s.originalBalance}. Reseed the demo user first.`,
    );
  }
});

Given('Alice has at least R{float} available', async (minimumBalance: number) => {
  const s = await initializeState();
  if (s.senderName !== 'Alice Ledger') {
    throw new Error(`Expected Alice Ledger to be signed in, but the API session belongs to "${s.senderName}"`);
  }
  if ((s.originalBalance as number) < round2(minimumBalance)) {
    throw new Error(
      `Precondition failed: Alice needs at least R${minimumBalance}, but the database has R${s.originalBalance}.`,
    );
  }
});

// ---------- the concurrent action ----------
When(
  'mobile transfers R{float} and web transfers R{float} simultaneously',
  async (mobileAmount: number, webAmount: number) => {
    const s = st();
    s.mobileAmount = mobileAmount;
    s.webAmount = webAmount;

    // both transfers must be affordable, otherwise "both succeed" cannot hold
    expect(s.originalBalance as number).toBeGreaterThanOrEqual(round2(mobileAmount + webAmount));

    // fill the mobile form, then bring the button into view WITHOUT tapping it
    await page.openTab('Transact');
    await transferPage.setAmount(mobileAmount);
    const button = await transferPage.reviewButton();

    const delayMs = Number(process.env.WEB_DELAY_MS ?? 0); // tune if the web call lands before the phone's request
    const fireAt = Date.now();

    const [, web] = await Promise.all([
      transferPage.tap(button),
      sleep(delayMs).then(() => transfer(s.web, s.recipientId as number, webAmount)),
    ]);
    s.webResult = web;
    s.mobileResult = await transferPage.waitForTransferResult();

    console.log(
      `[Concurrency] web call started +${web.startedAt - fireAt}ms after the tap command, took ${web.finishedAt - web.startedAt}ms`,
    );
  },
);

When(
  'Alice transfers R{float} to {string} and taps Review Transaction',
  async (amount: number, recipientName: string) => {
    const s = st();
    const recipient = (await getAccounts(s.web)).find((account) => account.full_name === recipientName);
    if (!recipient || recipient.id === s.web.userId) {
      throw new Error(`Could not find a transfer recipient named "${recipientName}"`);
    }
    if ((s.originalBalance as number) < round2(amount)) {
      throw new Error(`Alice's balance is too low to transfer R${amount}`);
    }

    s.recipientId = recipient.id;
    s.recipientName = recipientName;
    s.recipientBalance = round2(await getBalance(s.web, recipient.id));
    s.mobileAmount = amount;

    await page.openTab('Transact');
    const mobileBalance = round2(await page.transferScreenBalance());
    if (mobileBalance !== s.originalBalance) {
      throw new Error(
        `The mobile app balance is R${mobileBalance}, but Alice's API balance is R${s.originalBalance}`,
      );
    }
    await transferPage.tapBeneficiary(recipientName);
    await transferPage.setAmount(amount);
    await transferPage.tap(await transferPage.reviewButton());
    s.mobileResult = await transferPage.waitForTransferResult();
  },
);

// ---------- verification ----------
Then('both transfers should succeed', async () => {
  const s = st();
  if (!s.webResult?.ok) {
    throw new Error(`Web transfer failed: HTTP ${s.webResult?.httpStatus} ${JSON.stringify(s.webResult?.body)}`);
  }
  if (!s.mobileResult?.ok) {
    throw new Error(`Mobile transfer failed: ${s.mobileResult?.message || '(no message)'}`);
  }
});

Then('both transactions should be saved in the database', async () => {
  const s = st();

  // transfers queued for approval are authorised so they count towards the balance
  const queued = await waitForNewTransactions(s, 2);
  for (const tx of queued) {
    const latest = await getTransaction(s.web, tx.id);
    if (normaliseStatus(latest.status) === 'pending') await authorize(s.web, tx.id);
  }
  s.newTxs = await waitForNewTransactions(s, 2); // re-read after approvals

  const amounts = s.newTxs.map((t) => round2(Math.abs(Number(t.amount)))).sort((x, y) => x - y);
  expect(amounts).toEqual(
    [round2(s.mobileAmount as number), round2(s.webAmount as number)].sort((x, y) => x - y),
  );
});

Then('the final balance should be R{float}', async (expectedBalance: number) => {
  const s = st();
  const expected = round2(expectedBalance);

  // short poll only to absorb commit lag; a wrong value that never converges is a real failure
  let actual = round2(await getBalance(s.web));
  const deadline = Date.now() + 10000;
  while (actual !== expected && Date.now() < deadline) {
    await sleep(500);
    actual = round2(await getBalance(s.web));
  }
  if (actual === expected) return;

  const original = s.originalBalance as number;
  let hint = 'balance does not match either single debit';
  if (actual === round2(original - (s.mobileAmount as number))) hint = 'the WEB debit was lost (lost update / double-spend)';
  if (actual === round2(original - (s.webAmount as number))) hint = 'the MOBILE debit was lost (lost update / double-spend)';
  throw new Error(`Balance mismatch: expected ${expected}, database has ${actual} (original ${original}): ${hint}`);
});

Then('no duplicate transactions should exist', async () => {
  const s = st();
  await sleep(3000); // give a stray duplicate time to show up before the final read

  const history = await getHistory(s.web);
  const fresh = history.filter((t) => !(s.originalIds as Set<number>).has(t.id));

  // both amounts can be identical (50 and 50), so duplicates are judged by id and by count, not by amount
  expect(new Set(fresh.map((t) => t.id)).size).toBe(fresh.length);
  expect(fresh.length).toBe(2);
});

Then('the mobile transfer should be submitted successfully', async () => {
  const result = st().mobileResult;
  if (!result?.ok) {
    throw new Error(`Mobile transfer failed: ${result?.message || '(no success alert appeared)'}`);
  }
});

Then('the transfer should be completed from Alice to {string}', async (recipientName: string) => {
  const s = st();
  if (s.recipientName !== recipientName) {
    throw new Error(`Expected recipient "${recipientName}", but selected "${s.recipientName}"`);
  }

  const fresh = await waitForNewTransactions(s, 1);
  if (fresh.length !== 1) {
    throw new Error(`Expected one new transfer, but found ${fresh.length}`);
  }

  let transaction = await getTransaction(s.web, fresh[0].id);
  expect(Number(transaction.sender_account_id)).toBe(s.web.userId);
  expect(Number(transaction.recipient_account_id)).toBe(s.recipientId);
  expect(round2(Math.abs(Number(transaction.amount)))).toBe(round2(s.mobileAmount as number));

  const status = normaliseStatus(transaction.status);
  if (status === 'pending') {
    await authorize(s.web, transaction.id);
    transaction = await getTransaction(s.web, transaction.id);
  } else if (status !== 'completed') {
    throw new Error(`Expected a pending or completed transfer, received status "${transaction.status}"`);
  }
  expect(normaliseStatus(transaction.status)).toBe('completed');
  s.newTxs = [transaction];
});

Then(
  "Alice's balance should decrease by R{float} and {string} should increase by R{float}",
  async (debit: number, recipientName: string, credit: number) => {
    const s = st();
    if (s.recipientName !== recipientName) {
      throw new Error(`Expected recipient "${recipientName}", but selected "${s.recipientName}"`);
    }
    expect(round2(debit)).toBe(round2(s.mobileAmount as number));
    expect(round2(credit)).toBe(round2(s.mobileAmount as number));

    const expectedAliceBalance = round2((s.originalBalance as number) - debit);
    const expectedRecipientBalance = round2((s.recipientBalance as number) + credit);
    const deadline = Date.now() + 10000;
    let aliceBalance = round2(await getBalance(s.web));
    let recipientBalance = round2(await getBalance(s.web, s.recipientId as number));
    while (
      (aliceBalance !== expectedAliceBalance || recipientBalance !== expectedRecipientBalance) &&
      Date.now() < deadline
    ) {
      await sleep(500);
      aliceBalance = round2(await getBalance(s.web));
      recipientBalance = round2(await getBalance(s.web, s.recipientId as number));
    }

    expect(aliceBalance).toBe(expectedAliceBalance);
    expect(recipientBalance).toBe(expectedRecipientBalance);
  },
);

// Concurrent transfers: mobile (Appium UI) and web (separate API session) at the same moment.
// Same page objects, API client and helpers as concurrent_transfers.steps.ts.
// The feature has no Background, so the mobile login happens in the first Given step.
import { Given, When, Then } from '@wdio/cucumber-framework';
import { expect } from '@wdio/globals';
import page from './primefin.page';
import transferPage, { MobileTransferResult } from './transfer.page';
import { normaliseStatus, round2 } from '../support/helpers';
import {
  authorize, getAccounts, getBalance, getHistory, getTransaction, loginAs, transfer,
  HistoryTx, Session, TransferResult,
} from '../support/transferApi';

interface ConcurrencyState {
  web: Session;
  recipientId?: number;
  recipientName?: string;
  recipientBalance?: number;
  originalBalance?: number;
  originalIds?: Set<number>;
  mobileAmount?: number;
  webAmount?: number;
  webResult?: TransferResult;
  mobileResult?: MobileTransferResult;
  newTxs?: HistoryTx[];
}

let state: ConcurrencyState | undefined;
const st = (): ConcurrencyState => {
  if (!state) throw new Error('State missing: the "account balance is R..." step must run first');
  return state;
};
const sleep = (ms: number) => new Promise((r) => setTimeout(r, ms));

/** Polls the history until at least `atLeast` transactions that did not exist before the test are visible. */
async function waitForNewTransactions(s: ConcurrencyState, atLeast: number): Promise<HistoryTx[]> {
  const deadline = Date.now() + 10000;
  let fresh: HistoryTx[] = [];
  do {
    const history = await getHistory(s.web);
    fresh = history.filter((t) => !(s.originalIds as Set<number>).has(t.id));
    if (fresh.length >= atLeast) break;
    await sleep(500);
  } while (Date.now() < deadline);
  return fresh;
}

async function initializeState(): Promise<ConcurrencyState> {
  state = undefined;
  await page.login();
  await page.waitForBalanceLoaded();

  const s: ConcurrencyState = { web: await loginAs('web') };
  const accounts = await getAccounts(s.web);
  const recipient = accounts.find((a) => a.id !== s.web.userId);
  if (!recipient) throw new Error('The database needs a second account to act as the transfer recipient');
  s.recipientId = recipient.id;
  s.originalBalance = round2(await getBalance(s.web));
  s.originalIds = new Set((await getHistory(s.web)).map((t) => t.id));
  state = s;
  return s;
}

// ---------- setup ----------
Given('the account balance is R{float}', async (expectedBalance: number) => {
  const s = await initializeState();
  if (s.originalBalance !== round2(expectedBalance)) {
    throw new Error(
      `Precondition failed: expected the account balance to be R${expectedBalance}, but the database has R${s.originalBalance}. Reseed the demo user first.`,
    );
  }
});

Given('Alice has at least R{float} available', async (minimumBalance: number) => {
  const s = await initializeState();
  if ((s.originalBalance as number) < round2(minimumBalance)) {
    throw new Error(
      `Precondition failed: Alice needs at least R${minimumBalance}, but the database has R${s.originalBalance}.`,
    );
  }
});

// ---------- the concurrent action ----------
When(
  'mobile transfers R{float} and web transfers R{float} simultaneously',
  async (mobileAmount: number, webAmount: number) => {
    const s = st();
    s.mobileAmount = mobileAmount;
    s.webAmount = webAmount;

    // both transfers must be affordable, otherwise "both succeed" cannot hold
    expect(s.originalBalance as number).toBeGreaterThanOrEqual(round2(mobileAmount + webAmount));

    // fill the mobile form, then bring the button into view WITHOUT tapping it
    await page.openTab('Transact');
    await transferPage.setAmount(mobileAmount);
    const button = await transferPage.reviewButton();

    const delayMs = Number(process.env.WEB_DELAY_MS ?? 0); // tune if the web call lands before the phone's request
    const fireAt = Date.now();

    const [, web] = await Promise.all([
      transferPage.tap(button),
      sleep(delayMs).then(() => transfer(s.web, s.recipientId as number, webAmount)),
    ]);
    s.webResult = web;
    s.mobileResult = await transferPage.waitForTransferResult();

    console.log(
      `[Concurrency] web call started +${web.startedAt - fireAt}ms after the tap command, took ${web.finishedAt - web.startedAt}ms`,
    );
  },
);

When(
  'Alice transfers R{float} to {string} and taps Review Transaction',
  async (amount: number, recipientName: string) => {
    const s = st();
    const recipient = (await getAccounts(s.web)).find((account) => account.full_name === recipientName);
    if (!recipient || recipient.id === s.web.userId) {
      throw new Error(`Could not find a transfer recipient named "${recipientName}"`);
    }
    if ((s.originalBalance as number) < round2(amount)) {
      throw new Error(`Alice's balance is too low to transfer R${amount}`);
    }

    s.recipientId = recipient.id;
    s.recipientName = recipientName;
    s.recipientBalance = round2(await getBalance(s.web, recipient.id));
    s.mobileAmount = amount;

    await page.openTab('Transact');
    await transferPage.tapBeneficiary(recipientName);
    await transferPage.setAmount(amount);
    await transferPage.tapReviewTransaction();
    s.mobileResult = await transferPage.waitForTransferResult();
  },
);

// ---------- verification ----------
Then('both transfers should succeed', async () => {
  const s = st();
  if (!s.webResult?.ok) {
    throw new Error(`Web transfer failed: HTTP ${s.webResult?.httpStatus} ${JSON.stringify(s.webResult?.body)}`);
  }
  if (!s.mobileResult?.ok) {
    throw new Error(`Mobile transfer failed: ${s.mobileResult?.message || '(no message)'}`);
  }
});

Then('both transactions should be saved in the database', async () => {
  const s = st();

  // transfers queued for approval are authorised so they count towards the balance
  const queued = await waitForNewTransactions(s, 2);
  for (const tx of queued) {
    const latest = await getTransaction(s.web, tx.id);
    if (normaliseStatus(latest.status) === 'pending') await authorize(s.web, tx.id);
  }
  s.newTxs = await waitForNewTransactions(s, 2); // re-read after approvals

  const amounts = s.newTxs.map((t) => round2(Math.abs(Number(t.amount)))).sort((x, y) => x - y);
  expect(amounts).toEqual(
    [round2(s.mobileAmount as number), round2(s.webAmount as number)].sort((x, y) => x - y),
  );
});

Then('the final balance should be R{float}', async (expectedBalance: number) => {
  const s = st();
  const expected = round2(expectedBalance);

  // short poll only to absorb commit lag; a wrong value that never converges is a real failure
  let actual = round2(await getBalance(s.web));
  const deadline = Date.now() + 10000;
  while (actual !== expected && Date.now() < deadline) {
    await sleep(500);
    actual = round2(await getBalance(s.web));
  }
  if (actual === expected) return;

  const original = s.originalBalance as number;
  let hint = 'balance does not match either single debit';
  if (actual === round2(original - (s.mobileAmount as number))) hint = 'the WEB debit was lost (lost update / double-spend)';
  if (actual === round2(original - (s.webAmount as number))) hint = 'the MOBILE debit was lost (lost update / double-spend)';
  throw new Error(`Balance mismatch: expected ${expected}, database has ${actual} (original ${original}): ${hint}`);
});

Then('no duplicate transactions should exist', async () => {
  const s = st();
  await sleep(3000); // give a stray duplicate time to show up before the final read

  const history = await getHistory(s.web);
  const fresh = history.filter((t) => !(s.originalIds as Set<number>).has(t.id));

  // both amounts can be identical (50 and 50), so duplicates are judged by id and by count, not by amount
  expect(new Set(fresh.map((t) => t.id)).size).toBe(fresh.length);
  expect(fresh).toHaveLength(2);
});

Then('the mobile transfer should be submitted successfully', async () => {
  const result = st().mobileResult;
  if (!result?.ok) {
    throw new Error(`Mobile transfer failed: ${result?.message || '(no success alert appeared)'}`);
  }
});

Then('the transfer should be completed from Alice to {string}', async (recipientName: string) => {
  const s = st();
  if (s.recipientName !== recipientName) {
    throw new Error(`Expected recipient "${recipientName}", but selected "${s.recipientName}"`);
  }

  const fresh = await waitForNewTransactions(s, 1);
  if (fresh.length !== 1) {
    throw new Error(`Expected one new transfer, but found ${fresh.length}`);
  }

  let transaction = await getTransaction(s.web, fresh[0].id);
  expect(Number(transaction.sender_account_id)).toBe(s.web.userId);
  expect(Number(transaction.recipient_account_id)).toBe(s.recipientId);
  expect(round2(Math.abs(Number(transaction.amount)))).toBe(round2(s.mobileAmount as number));

  const status = normaliseStatus(transaction.status);
  if (status === 'pending') {
    await authorize(s.web, transaction.id);
    transaction = await getTransaction(s.web, transaction.id);
  } else if (status !== 'completed') {
    throw new Error(`Expected a pending or completed transfer, received status "${transaction.status}"`);
  }
  expect(normaliseStatus(transaction.status)).toBe('completed');
  s.newTxs = [transaction];
});

Then(
  "Alice's balance should decrease by R{float} and {string} should increase by R{float}",
  async (debit: number, recipientName: string, credit: number) => {
    const s = st();
    if (s.recipientName !== recipientName) {
      throw new Error(`Expected recipient "${recipientName}", but selected "${s.recipientName}"`);
    }
    expect(round2(debit)).toBe(round2(s.mobileAmount as number));
    expect(round2(credit)).toBe(round2(s.mobileAmount as number));

    const expectedAliceBalance = round2((s.originalBalance as number) - debit);
    const expectedRecipientBalance = round2((s.recipientBalance as number) + credit);
    const deadline = Date.now() + 10000;
    let aliceBalance = round2(await getBalance(s.web));
    let recipientBalance = round2(await getBalance(s.web, s.recipientId as number));
    while (
      (aliceBalance !== expectedAliceBalance || recipientBalance !== expectedRecipientBalance) &&
      Date.now() < deadline
    ) {
      await sleep(500);
      aliceBalance = round2(await getBalance(s.web));
      recipientBalance = round2(await getBalance(s.web, s.recipientId as number));
    }

    expect(aliceBalance).toBe(expectedAliceBalance);
    expect(recipientBalance).toBe(expectedRecipientBalance);
  },
);

/** API client used by the E2E "web channel" and for database-side verification. */

const API_URL = process.env.API_URL ?? 'http://localhost:4000';
const EMAIL = process.env.APP_EMAIL ?? 'alice@flashguard.local';
const PASSWORD = process.env.APP_PASSWORD ?? 'offline-demo';

export interface Session { token: string; userId: number; channel: string }
export interface Account { id: number; full_name?: string; email?: string }
export interface HistoryTx {
  id: number;
  amount: number | string;
  status?: string;
  title?: string;
  created_at?: string;
}
export interface TransferResult {
  ok: boolean;
  httpStatus: number;
  body: any;
  startedAt: number;
  finishedAt: number;
}

const authHeaders = (token?: string) => ({
  'Content-Type': 'application/json',
  ...(token ? { Authorization: `Bearer ${token}` } : {}),
});

async function call<T>(method: 'GET' | 'POST', path: string, token?: string, body?: unknown): Promise<T> {
  const res = await fetch(`${API_URL}${path}`, {
    method,
    headers: authHeaders(token),
    body: body === undefined ? undefined : JSON.stringify(body),
  });
  const json: any = await res.json().catch(() => ({}));
  if (!res.ok) throw new Error(`${method} ${path} -> ${res.status}: ${json?.message ?? 'request failed'}`);
  return json as T;
}

/** A separate login = a separate session, like opening the web app next to the phone. */
export async function loginAs(channel: 'web' | 'test-runner' = 'web'): Promise<Session> {
  const body = await call<{ token: string; user: { id: number } }>('POST', '/auth/login', undefined, {
    email: EMAIL,
    password: PASSWORD,
    deviceMetadata: { platform: channel, alias: channel === 'web' ? 'chrome-desktop' : 'test-runner' },
  });
  return { token: body.token, userId: body.user.id, channel };
}

export const getAccounts = (s: Session) => call<Account[]>('GET', '/accounts', s.token);

export async function getBalance(s: Session): Promise<number> {
  const body = await call<{ balance: number | string }>('GET', `/accounts/${s.userId}/balance`, s.token);
  return Number(body.balance);
}

export const getHistory = (s: Session) => call<HistoryTx[]>('GET', '/transactions/history', s.token);
export const getTransaction = (s: Session, id: number) => call<HistoryTx>('GET', `/transactions/${id}`, s.token);
export const authorize = (s: Session, id: number) =>
  call<unknown>('POST', `/transactions/transfer/${id}/authorize`, s.token);

/** Same payload the mobile app sends. Does NOT throw on failure, so the step can report both channels. */
export async function transfer(s: Session, recipientAccountId: number, amount: number): Promise<TransferResult> {
  const startedAt = Date.now();
  const res = await fetch(`${API_URL}/transactions/transfer`, {
    method: 'POST',
    headers: authHeaders(s.token),
    body: JSON.stringify({ senderAccountId: s.userId, recipientAccountId, amount }),
  });
  const body = await res.json().catch(() => ({}));
  return { ok: res.ok, httpStatus: res.status, body, startedAt, finishedAt: Date.now() };
}

// WebdriverIO provides these globals when the test runner starts.
declare const $: (selector: string) => any;
declare const browser: any;
declare const driver: any;

/** Mobile "Transact" screen actions used by the transfer E2E scenarios. */

const esc = (v: string) => v.replace(/"/g, '\\"');
const byText = (v: string) => `android=new UiSelector().text("${esc(v)}")`;
const amountInputSelector = 'new UiSelector().resourceId("transfer-amount")';
const amountInputLocator = `android=${amountInputSelector}`;
const reviewButtonSelector = 'new UiSelector().resourceId("transfer-submit")';

export interface MobileTransferResult { ok: boolean; title: string; message: string }

class TransferPage {
  /** Swipes up to reveal later fields lower in the Transact form. */
  private async scrollTo(uiSelector: string) {
    const target = $(`android=${uiSelector}`);
    const scrollView = await $('android=new UiSelector().scrollable(true)');
    await scrollView.waitForDisplayed({ timeout: 10000 });
    const location = await scrollView.getLocation();
    const size = await scrollView.getSize();
    const left = location.x + Math.round(size.width * 0.05);
    const top = location.y + Math.round(size.height * 0.12);
    const width = Math.round(size.width * 0.9);
    const height = Math.round(size.height * 0.75);

    for (let swipe = 0; swipe < 10; swipe += 1) {
      if (await target.isDisplayed()) return target;
      await driver.execute('mobile: swipeGesture', {
        left,
        top,
        width,
        height,
        direction: 'up',
        percent: 0.75,
      });
    }

    if (await target.isDisplayed()) return target;
    throw new Error(`Could not scroll down to "${uiSelector}" within the Transact form`);
  }

  /** Use a stable test ID because the amount text changes as the controlled input updates. */
  async setAmount(amount: number) {
    await this.scrollTo('new UiSelector().text("Transfer Details")');
    const input = await this.scrollTo(amountInputSelector);
    await input.click();
    await input.clearValue();
    const refreshedInput = $(amountInputLocator);
    await refreshedInput.waitForDisplayed({ timeout: 10000 });
    await refreshedInput.addValue(String(amount));
    await browser.waitUntil(async () => (await $(amountInputLocator).getText()) === String(amount), {
      timeout: 5000,
      timeoutMsg: `Transfer amount did not update to ${amount}`,
    });
    if (await driver.isKeyboardShown()) {
      await driver.pressKeyCode(4);
      await browser.waitUntil(async () => !(await driver.isKeyboardShown()), {
        timeout: 5000,
        timeoutMsg: 'Android keyboard remained open after pressing Back',
      });
    }
  }

  async tapBeneficiary(name: string) {
    await this.scrollTo(`new UiSelector().text("${esc(name)}")`);
    const row = await $(
      `//android.widget.TextView[@text="${esc(name)}"]/ancestor::android.view.ViewGroup[@clickable="true"][1]`,
    );
    await row.waitForDisplayed({ timeout: 10000 });
    await row.click();
  }

  /** Brings the Review Transaction button into view. */
  async reviewButton() {
    return this.scrollTo(reviewButtonSelector);
  }

  async tapReviewTransaction() {
    const button = await this.reviewButton();
    await $(byText('Review Transaction')).waitForDisplayed({
      timeout: 5000,
      timeoutMsg: 'Review Transaction label was not visible',
    });
    await button.click();
    await browser.waitUntil(
      async () =>
        (await $(byText('Submitting...')).isDisplayed()) ||
        (await $(byText('Transfer submitted')).isDisplayed()) ||
        (await $(byText('Transfer failed')).isDisplayed()),
      {
        timeout: 10000,
        timeoutMsg: 'Tapping Review Transaction did not start a submission',
      },
    );
  }

  async tap(el: { click: () => Promise<void> }) {
    await el.click();
  }

  /** App.js shows an Alert: "Transfer submitted" on success, "Transfer failed" + server message otherwise. */
  async waitForTransferResult(timeout = 20000): Promise<MobileTransferResult> {
    const isUp = async (text: string) => $(byText(text)).isDisplayed();
    await browser.waitUntil(async () => (await isUp('Transfer submitted')) || (await isUp('Transfer failed')), {
      timeout,
      timeoutMsg: 'Neither "Transfer submitted" nor "Transfer failed" appeared on the mobile app',
    });
    const ok = await isUp('Transfer submitted');
    let message = '';
    try {
      message = await $('id=android:id/message').getText();
    } catch {
      /* no message text */
    }
    await $('id=android:id/button1').click();
    return { ok, title: ok ? 'Transfer submitted' : 'Transfer failed', message };
  }

  async restartApp() {
    const appPackage = await driver.getCurrentPackage();
    await driver.terminateApp(appPackage);
    await driver.activateApp(appPackage);
  }
}

export default new TransferPage();

declare const require: (moduleName: string) => {
  execFileSync: (...args: any[]) => string;
};
declare const process: {
  env: Record<string, string | undefined>;
};

const { execFileSync } = require('child_process');

export function executeSql(query: string): string {
  const useWindowsAuth = process.env.DB_AUTH?.toLowerCase() === 'windows';
  const args = [
    '-S', `${process.env.DB_HOST || 'localhost'},${process.env.DB_PORT || '1433'}`,
  ];

  if (useWindowsAuth) {
    args.push('-E');
  } else {
    const password = process.env.DB_PASSWORD;
    if (!password) {
      throw new Error('Set DB_AUTH=windows or provide DB_PASSWORD to query SQL Server in E2E tests.');
    }
    args.push('-U', process.env.DB_USER || 'fg', '-P', password);
  }

  args.push(
    '-d', process.env.DB_NAME || 'FlashGuard',
    '-C',
    '-b',
    '-h', '-1',
    '-W',
    '-s', '|',
    '-Q', query
  );

  try {
    return execFileSync(
      'sqlcmd',
      args,
      {
        encoding: 'utf8',
        env: process.env,
        stdio: ['ignore', 'pipe', 'pipe']
      }
    ).trim();
  } catch (error: any) {
    throw new Error(
      `SQL Server query failed: ${error.stderr || error.message}`
    );
  }
}

export function getLatestLoginAuditId(accountId: number): number {
  const result = executeSql(`
    SET NOCOUNT ON;

    SELECT ISNULL(MAX(id), 0)
    FROM dbo.audit_log
    WHERE account_id = ${accountId}
      AND action = 'login';
  `);

  const id = Number(result);

  if (!Number.isInteger(id)) {
   throw new Error(`Unexpected SQL result: ${result}`);
  }

  return id;
}

